export const meta = {
  name: 'multi_perspective_analysis',
  description: "Analyze from 5 different perspectives",
  phases: [
    { title: 'Perspective Analysis' },
    { title: 'Synthesis' },
  ],
};

phase('Perspective Analysis');
const topic = "Draft 3 benchmark briefs (task prompts) for measuring a task-orchestration skill headlessly. Each brief must: (1) be a single self-contained instruction runnable in a seeded empty directory; (2) force plan-then-execute behavior (not a one-shot answer) — shapes: (a) research+synthesis producing a cited report from seeded source files, (b) multi-file change requiring inspection before editing, (c) exploratory debugging with a verification loop; (3) include 2-3 objective pass/fail canaries (exact filenames, content markers, counts); (4) complete in under 6 tool rounds. For each of the 3 briefs output: exact prompt text, seed files (name+content), canary checks. Judge each for canary determinism, cost discipline, and whether it truly forces planning before acting.";
const analyses = await parallel([
  () => agent("Analyze from technical perspective: " + topic, { label: "technical" }),
  () => agent("Analyze from product perspective: " + topic, { label: "product" }),
  () => agent("Analyze from security perspective: " + topic, { label: "security" }),
  () => agent("Analyze from user experience perspective: " + topic, { label: "user-experience" }),
  () => agent("Analyze from maintainability perspective: " + topic, { label: "maintainability" }),
]);

phase('Synthesis');
const synthesis = await agent(
  'Synthesize these different perspectives into a balanced analysis:\n' +
  'Analyses: ' + JSON.stringify(analyses) + '\n' +
  'Topic: ' + topic,
  { label: 'synthesizer' }
);

return { analyses, synthesis };

